        if not t_in.is_contiguous():
            t_in = t_in.contiguous()
        n_total = B * n
        # Single program per copy: smallest power-of-2 BLOCK covering n_total,
        # so every workload launches exactly one program and avoids per-program
        # launch overhead (the op is launch-bound, not memory-bound).
